ASYNC_MAX = 4        #: background delegations reaching a model at once; the rest wait as `pending`
ASYNC_KEEP = 50      #: answers held before the oldest is dropped

class Background:
    "Delegations running behind the turn that asked for them, and the answers they leave."
    def __init__(self,
                 mx=ASYNC_MAX,        # how many reach a model at once
                 keep=ASYNC_KEEP,     # answers held before the oldest is dropped
                 on_done=None):       # called with `(run, answer)` when a run finishes
        self.sem = threading.Semaphore(max(1, int(mx)))
        self.keep, self.lock, self.open, self.on_done = max(1, int(keep)), threading.Lock(), True, on_done
        self.runs, self.answers, self.seen = {}, {}, set()

    def _live(self, run):
        "Whether `run` should still reach a model; closing or cancelling stops it."
        with self.lock: ok = self.open
        if ok and not run.cancelled: return True
        if not run.terminal: run.finish('cancelled')
        return False

    def _answer(self, rid, text):
        with self.lock:
            self.answers[rid], _ = text, self.seen.add(rid)
            for old in list(self.answers)[:-self.keep]: self.answers.pop(old, None)
            for old in list(self.runs)[:-self.keep * 2]:
                self.runs.pop(old, None)
                self.seen.discard(old)

    def start(self, fn, run):
        "Register `run`, then work `fn(run)` on a daemon thread; return its id."
        with self.lock:
            if not self.open: raise AgentError('nothing new starts while the session is closing')
            self.runs[run.id] = run
        def work():
            if not self._live(run): return self._answer(run.id, _stopped(run))
            with self.sem:
                if not self._live(run): return self._answer(run.id, _stopped(run))
                try: out = fn(run)
                except Exception as e: out = err('delegation failed', e) + bad_json(e)
            self._answer(run.id, out)
            if not run.terminal: run.finish()
            if self.on_done: self.on_done(run, out)
        threading.Thread(target=contextvars.copy_context().run, args=(work,), daemon=True, name=f'ramabana-bg-{run.id}').start()
        return run.id

    def status(self, run_id=''):
        "Rows for every registered run, or one; a miss returns text, not an empty list."
        with self.lock: runs = dict(self.runs)
        if not run_id: return [r.dict() for r in runs.values()]
        r = runs.get(str(run_id))
        return [r.dict()] if r is not None else f'no delegation named {run_id!r} was started here'

    def result(self, run_id):
        "The answer `run_id` left, or what it is still doing."
        with self.lock:
            rid = str(run_id)
            run, ans, held = self.runs.get(rid), self.answers.get(rid), rid in self.seen
        if run is None: return f'no delegation named {run_id!r} was started here'
        if ans is not None: return ans
        if held: return f'{run_id} finished ({run.state}) and its answer is no longer held'
        return f'{run_id} is {run.state}; ask again later'

    def cancel(self, run_id):
        "Stop one run; its answer becomes the stopped notice."
        with self.lock: run = self.runs.get(str(run_id))
        if run is None: return f'no delegation named {run_id!r} was started here'
        if run.terminal: return f'{run_id} had already finished ({run.state})'
        run.request_cancel()
        return f'{run_id} is stopping'

    def close(self):
        "Refuse new work and cancel what runs; queued runs never reach a model."
        with self.lock: self.open, runs = False, list(self.runs.values())
        for r in runs: r.request_cancel()
        return len(runs)


# %% ../nbs/02_tools.ipynb #906e7f69
def named_skills(get_skills, names):
    "The skills a delegated task named, and a note about any name that matched nothing."
    if not names or get_skills is None: return [], ''
    every = list(get_skills() or [])
    got, missing = [], []
    for n in [x for x in str(names).replace(',', ' ').split() if x]:
        s = find(every, n)
        got.append(s) if s is not None else missing.append(n)
    if not missing: return got, ''
    return got, (f"\n\n[no skill named {', '.join(missing)}; this repository has "
                 f"{', '.join(s.name for s in every) or 'none'}]")


MAX_MEDIA = 20 << 20   #: max bytes of one attached picture or sound
MAX_ATTACH = 8         #: attachments one message carries

def picture_mime(head):
    "The MIME of a PNG, JPEG, GIF or WebP from its first bytes, else None."
    head = bytes(head or b'')
    if head[:4] == b'RIFF' and head[8:12] == b'WEBP': return 'image/webp'
    sigs = ((b'\x89PNG\r\n\x1a\n', 'image/png'), (b'\xff\xd8\xff', 'image/jpeg'), (b'GIF87a', 'image/gif'), (b'GIF89a', 'image/gif'))
    return next((m for sig, m in sigs if head.startswith(sig)), None)

def read_pictures(host, paths):
    "`(bytes, '')` for pictures inside the host's roots, or `([], err)` for the first one refused."
    paths = [paths] if isinstance(paths, str) else list(paths or [])
    if len(paths) > MAX_ATTACH: return [], err(f'{len(paths)} pictures; send at most {MAX_ATTACH}')
    out = []
    for s in paths:
        try: p = host.check(s, must_exist=True, reading=True)
        except Exception as e: return [], err(f'cannot use {s}', e)
        if p.stat().st_size > MAX_MEDIA: return [], err(f'{p} is over the {MAX_MEDIA >> 20} MB a picture may be')
        with open(p, 'rb') as f:
            if picture_mime(f.read(16)) is None: return [], err(f'not a picture: {p}', 'a PNG, JPEG, WebP or GIF by its bytes')
        out.append(p.read_bytes())
    return out, ''


def subagent_tools(get_backend, get_tools, get_skills=None, get_cloud_backend=None,
                   get_writes=None,     # the session's sub-agent write toggle, read per call
                   get_approve=None,    # the gate those writes answer to
                   background=None,     # async delegation register; made if None
                   get_log_dir=None,    # callable -> the folder run transcripts go in, or None
                   get_pictures=None):  # callable paths -> `(bytes, err)`; see `read_pictures`
    "The delegation tools, routed to the configured sub-agent backend. Arguments are callables, read per call."
    bg = ifnone(background, Background())
    def _writes(): return bool(get_writes()) if get_writes is not None else False
    def _approve(): return get_approve() if (get_approve is not None and _writes()) else None

    def _questions(qs):
        "Non-empty question texts from a list or its JSON text; any other string is one question."
        if isinstance(qs, str) and qs.strip().startswith('['):
            try: qs = json.loads(qs)
            except Exception: pass
        return [str(q).strip() for q in (qs if isinstance(qs, (list, tuple)) else [qs]) if str(q).strip()]

    def _pictures(b, paths):
        "`(bytes, note, '')` for the pictures a delegation names, or `([], '', err)`."
        if not paths: return [], '', ''
        if get_pictures is None: return [], '', err('this session cannot read pictures for a sub-agent')
        if not accepts(b.spec, 'image'): return [], '', err(f'{b.spec.name} cannot be sent pictures')
        pics, refused = get_pictures(paths)
        names = [paths] if isinstance(paths, str) else list(paths)
        return pics, f"\n\n[pictures attached, in order: {', '.join(map(str, names))}]", refused

    @acts
    @summary(lambda a: (lambda qs: f'Delegate: {_1(qs[0], 120)}' if len(qs) == 1 else f'Delegate {len(qs)} questions: {_1("; ".join(qs), 100)}')(_questions(a.get('questions', []))))
    def delegate_search(questions: list[str], skills: str = '',
                        cloud_model: str = '',   # empty runs the configured sub-agent model
                        images: list[str] = [],  # pictures in the open folders each sub-agent sees with its question
                        ) -> str:
        "Delegate self-contained questions to sub-agents and return only their conclusions: one question runs one sub-agent, several run concurrently."
        qs = _questions(questions)
        if not qs: return 'no questions given'
        b = get_cloud_backend(cloud_model) if cloud_model and get_cloud_backend is not None else get_backend()
        if b is None: return (f'no model is available to delegate to ({cloud_model}); leave `cloud_model` empty to use the sub-agent model'
                              if cloud_model else 'no model is available to delegate to')
        pics, seen, refused = _pictures(b, images)
        if refused: return refused
        if len(pics) * len(qs) > MAX_ATTACH:   # every question's sub-agent is sent every picture
            return err(f'{len(pics)} pictures to {len(qs)} questions is {len(pics) * len(qs)} sent; at most {MAX_ATTACH} in all, so ask fewer questions or send fewer pictures')
        sk, note = named_skills(get_skills, skills)
        if len(qs) == 1:
            return clip(delegate(b, qs[0] + seen, get_tools(), skills=sk, writes=_writes(), approve=_approve(), images=pics), MAX_TOOL_CHARS) + note
        answers = delegate_many(b, [q + seen for q in qs], get_tools(), skills=sk, writes=_writes(), approve=_approve(), images=pics)
        return clip('\n\n'.join(f'### {q}\n{a}' for q, a in zip(qs, answers)), MAX_TOOL_CHARS * 2) + note

    @acts
    @summary(lambda a: f'Delegate in the background: {_1(a.get("question"), 110)}')
    def delegate_async(question: str, skills: str = '', writes: bool = False,
                       images: list[str] = [],  # pictures in the open folders the sub-agent sees with its question
                       ) -> str:
        "Start a background sub-agent and return its run id for `delegate_result`; `writes=True` is refused while sub-agents are read-only."
        b = get_backend()
        if b is None: return 'no model is available to delegate to'
        if writes and not _writes():
            return err('sub-agents are read-only this session; ask the user for `/subagents on` or delegate read-only')
        pics, seen, refused = _pictures(b, images)
        if refused: return refused
        sk, note = named_skills(get_skills, skills)
        rid, d = f'run_{uuid.uuid4().hex[:12]}', get_log_dir() if get_log_dir is not None else None
        child = Run(rid, 'background', str(question), b.spec.name, log=None if d is None else Path(d)/f'{rid}.log')
        try: rid = bg.start(lambda r: delegate(b, question + seen, get_tools(), skills=sk, writes=writes,
                       approve=_approve() if writes else None, run=r, images=pics), child)
        except Exception as e: return err('could not start the delegation', e)
        asked = 'with write tools' if writes else 'read-only'
        return f'started {rid} ({asked}). Collect it with delegate_result({rid!r}).' + note

    @acts
    @summary(lambda a: f'Collect delegation {a["run_id"]}' if a.get('run_id') else 'List the background delegations')
    def delegate_result(run_id: str = '') -> str:
        "The answer a background delegation left, or what it is still doing; with no `run_id`, every delegation started this session and its state."
        if run_id: return clip(bg.result(run_id), MAX_TOOL_CHARS)
        rows = bg.status('')
        if isinstance(rows, str): return rows
        if not rows: return 'nothing has been delegated in the background'
        return clip('\n'.join(f"{r['id']}  {r['state']:10} {r['question'][:80]}" for r in rows), MAX_TOOL_CHARS)

    @acts
    @summary(lambda a: f'Cancel delegation {a.get("run_id","?")}')
    def delegate_cancel(run_id: str) -> str:
        "Stop a background delegation. What it had already done is not undone."
        return bg.cancel(run_id)

    return [delegate_search, delegate_async, delegate_result, delegate_cancel]

